// coarse grid of trees for fast "under canopy" lookups
const CELL = 10, treeGrid = new Map();
for (const tp of treePositions) {
  const key = Math.floor(tp.x / CELL) + ',' + Math.floor(tp.z / CELL);
  (treeGrid.get(key) || treeGrid.set(key, []).get(key)).push(tp);
}
function canopyShade(x, z) {
  const cx = Math.floor(x / CELL), cz = Math.floor(z / CELL);
  let shade = 1;
  for (let i = -1; i <= 1; i++) for (let j = -1; j <= 1; j++) {
    const cell = treeGrid.get((cx + i) + ',' + (cz + j));
    if (!cell) continue;
    for (const tp of cell) {
      const d = Math.hypot(x - tp.x, z - tp.z);
      const r = 3.4 * tp.s;
      if (d < r) shade = Math.min(shade, 0.45 + 0.55 * (d / r));
    }
  }
  return shade;
}

